import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from 'react'
import { Bell, CalendarDays, CheckCheck, ChevronLeft, ChevronRight, ClipboardList, Clock, CreditCard, Download, Eye, EyeOff, FileHeart, FileText, History, LayoutDashboard, List, LockKeyhole, LogOut, MapPin, MessageCircle, Phone, Plus, QrCode, Search, Star, Stethoscope, UserRound, X } from 'lucide-react'
import FullCalendar from '@fullcalendar/react'
import dayGridPlugin from '@fullcalendar/daygrid'
import timeGridPlugin from '@fullcalendar/timegrid'
import frLocale from '@fullcalendar/core/locales/fr'
import arLocale from '@fullcalendar/core/locales/ar'
import enGbLocale from '@fullcalendar/core/locales/en-gb'
import { apiCreate, apiDownload, apiGet, apiList, apiPatch, apiPreview, apiUpdate } from '../../lib/api'
import { getSession, logout } from '../../lib/auth'
import { Trans, useTranslation } from 'react-i18next'
import { WorkspaceNavButton } from '../../components/WorkspaceNavButton'
import { CabinetLocationMap } from '../../components/CabinetLocationMap'
import { InterfaceLanguageSettings } from '../../components/InterfaceLanguageSettings'

type Settings={patient_can_request_appointment:boolean;patient_can_confirm_appointment:boolean;patient_can_cancel_appointment:boolean;patient_can_view_payments:boolean;patient_can_download_documents:boolean;patient_requires_validation:boolean}
type Profile={tenant_id:string;first_name:string;last_name:string;email:string;phone:string|null;birth_date:string;gender:string|null;address:string|null;status:string;cabinet_name:string;cnss_deposit_reminder_days:number;settings:Settings}
type PublicDoctor={id:string;tenant_id:string;name:string;specialty:string;cabinet:string;city:string;address?:string|null}
type AvailabilityDay={date:string;slots:Array<{start_time:string;end_time:string}>}
type PatientAppointment={id:string;doctor_id:string;doctor_name:string|null;doctor_specialty:string|null;cabinet_name:string|null;cabinet_address:string|null;cabinet_city:string|null;cabinet_phone:string|null;date:string;start_time:string;end_time:string;reason:string|null;status:string}
type AppointmentQr={appointment_id:string;qr_payload:string;qr_svg:string;patient_name:string;doctor_name:string|null;date:string;start_time:string;end_time:string;status:string;active:boolean;scanned_at:string|null}
const appointmentStatuses:Record<string,{label:string;style:string}>={requested:{label:'En attente',style:'bg-amber-50 text-amber-700'},planned:{label:'Planifié',style:'bg-blue-50 text-blue-700'},confirmed:{label:'Confirmé',style:'bg-emerald-50 text-emerald-700'},arrived:{label:'Arrivé',style:'bg-cyan-50 text-cyan-700'},waiting:{label:'Arrivé',style:'bg-cyan-50 text-cyan-700'},in_progress:{label:'En consultation',style:'bg-violet-50 text-violet-700'},completed:{label:'Terminé',style:'bg-slate-100 text-slate-700'},cancelled:{label:'Annulé',style:'bg-red-50 text-red-700'},rejected:{label:'Refusé',style:'bg-red-50 text-red-700'},absent:{label:'Absent',style:'bg-orange-50 text-orange-700'}}
const links=[['dashboard','/patient/dashboard',LayoutDashboard],['findDoctor','/patient/find-doctor',Search],['myAppointments','/patient/appointments',CalendarDays],['visitHistory','/patient/visits',History],['myDocuments','/patient/documents',FileText],['myPrescriptions','/patient/prescriptions',FileHeart],['myCnss','/patient/cnss',ClipboardList],['myPayments','/patient/payments',CreditCard],['whatsapp','/patient/communication-preferences',MessageCircle],['myProfile','/patient/profile',UserRound]] as const
type PatientNotificationItem={id:string;tenant_id:string;cabinet_name:string;type:string;title:string;message:string;resource_id:string|null;read_at:string|null;created_at:string}

function PatientNotificationBell(){
  const {t,i18n}=useTranslation()
  const token=getSession()?.accessToken??''
  const[open,setOpen]=useState(false);const[rows,setRows]=useState<PatientNotificationItem[]>([]);const[error,setError]=useState('')
  const load=useCallback(()=>{if(!token)return Promise.resolve();return apiList<PatientNotificationItem>('/patient/notifications',token).then(setRows).catch(reason=>setError(reason instanceof Error?reason.message:'Notifications indisponibles.'))},[token])
  useEffect(()=>{void load()},[load])
  const unread=rows.filter(item=>!item.read_at).length
  async function read(item:PatientNotificationItem){if(item.read_at)return;try{const result=await apiPatch<{read_at:string}>(`/patient/notifications/${item.id}/read`,token,{});setRows(current=>current.map(row=>row.id===item.id?{...row,read_at:result.read_at}:row))}catch(reason){setError(reason instanceof Error?reason.message:'Lecture impossible.')}}
  async function readAll(){try{await apiPatch('/patient/notifications/read-all',token,{});const now=new Date().toISOString();setRows(current=>current.map(row=>({...row,read_at:row.read_at??now})))}catch(reason){setError(reason instanceof Error?reason.message:'Lecture impossible.')}}
  return <div className="relative"><button type="button" onClick={()=>setOpen(value=>!value)} aria-label={t('notifications')} aria-expanded={open} className="relative grid h-10 w-10 place-items-center rounded-full text-slate-600 hover:bg-atlas-mist hover:text-atlas-teal"><Bell size={20}/>{unread>0&&<span className="absolute -end-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-red-600 px-1 text-[10px] font-black text-white ring-2 ring-white">{unread>9?'9+':unread}</span>}</button>{open&&<div className="absolute end-0 top-12 z-[70] w-[min(92vw,420px)] overflow-hidden rounded-2xl border border-atlas-line bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-atlas-line p-4"><div><h2 className="font-display text-lg font-bold">{t('notifications')}</h2><p className="text-xs text-slate-500">{t('patientAllPractices')}</p></div>{unread>0&&<button type="button" onClick={()=>void readAll()} className="inline-flex items-center gap-1.5 text-xs font-bold text-atlas-teal"><CheckCheck size={15}/>{t('markAllRead')}</button>}</div>{error&&<p className="m-3 rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700">{error}</p>}<div className="max-h-[65vh] overflow-y-auto">{rows.map(item=><button type="button" key={item.id} onClick={()=>void read(item)} className={`block w-full border-b border-atlas-line p-4 text-start last:border-0 ${item.read_at?'bg-white':'bg-atlas-mist/55'} hover:bg-slate-50`}><div className="flex items-start justify-between gap-3"><div><p className="text-[11px] font-black uppercase tracking-wide text-atlas-teal">{item.cabinet_name}</p><p className="mt-1 text-sm font-bold text-slate-900">{item.title}</p></div>{!item.read_at&&<span className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-red-500"/>}</div><p className="mt-2 text-sm leading-5 text-slate-600">{item.message}</p><p className="mt-2 text-[11px] text-slate-400">{new Date(item.created_at).toLocaleString(i18n.language)}</p></button>)}{!rows.length&&!error&&<div className="p-8 text-center"><Bell className="mx-auto text-slate-300" size={30}/><p className="mt-3 text-sm font-bold text-slate-600">{t('noNotifications')}</p></div>}</div></div>}</div>
}

export function PatientLayout({children,onNavigate,profile}:{children:ReactNode;onNavigate:(p:string)=>void;profile:Profile|null}){const{t}=useTranslation();const visible=links.filter(([,path])=>path!=='/patient/payments'||profile?.settings.patient_can_view_payments!==false);return <main className="min-h-screen bg-atlas-cloud text-atlas-ink"><header className="sticky top-0 z-40 border-b border-atlas-line bg-white/95 shadow-sm backdrop-blur-xl"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-4 px-4 py-3 md:px-7"><div className="flex min-w-0 items-center gap-4"><img src="/images/fadaa-logo.svg" alt="FADAA Santé" className="h-11 w-32 shrink-0 object-contain"/><div className="hidden min-w-0 border-s border-atlas-line ps-4 sm:block"><p className="truncate text-xs font-bold text-slate-500">{profile?.cabinet_name??t('healthSpace')}</p><span className="text-xs font-bold text-atlas-teal">{t('patientSpace')}</span></div></div><div className="flex shrink-0 items-center gap-1"><PatientNotificationBell/><button onClick={()=>{logout();onNavigate('/login')}} className="inline-flex items-center gap-2 rounded-lg px-3 py-2 text-sm font-bold text-red-600 hover:bg-red-50"><LogOut size={17}/> <span className="hidden sm:inline">{t('logout')}</span></button></div></div><nav className="mx-auto flex max-w-[1500px] gap-1 overflow-x-auto scroll-smooth border-t border-atlas-line/70 px-4 py-2 md:px-7">{visible.map(([label,path,Icon])=><WorkspaceNavButton key={path} onClick={()=>onNavigate(path)} active={location.pathname===path||location.pathname.startsWith(`${path}/`)} icon={Icon} layoutId="patient-active-nav">{t(label)}</WorkspaceNavButton>)}</nav></header><section>{children}</section></main>}

function useProfile(){const token=getSession()?.accessToken??'';const[p,setP]=useState<Profile|null>(null);useEffect(()=>{apiGet<Profile>('/patient/profile',token).then(setP)},[token]);return {token,profile:p,setProfile:setP}}
const Header=({title,subtitle}:{title:string;subtitle:string})=>{const{t}=useTranslation();return <header><p className="text-xs font-bold uppercase tracking-widest text-atlas-teal">{t('healthSpace')}</p><h1 className="mt-2 font-display text-3xl font-bold">{t(title)}</h1><p className="mt-2 text-sm text-slate-500">{t(subtitle)}</p></header>}
const Shell=({children,onNavigate,profile}:{children:ReactNode;onNavigate:(p:string)=>void;profile:Profile|null})=><PatientLayout onNavigate={onNavigate} profile={profile}><div className="mx-auto max-w-6xl p-5 md:p-8">{children}</div></PatientLayout>

export function PatientDashboard({onNavigate}:{onNavigate:(p:string)=>void}){
  const{t}=useTranslation();const{token,profile}=useProfile();const[data,setData]=useState<any>();const[fallbackFinance,setFallbackFinance]=useState<{fees:any[];payments:any[]}>({fees:[],payments:[]})
  useEffect(()=>{apiGet('/patient/dashboard',token).then(setData);Promise.allSettled([apiList<any>('/patient/honoraires',token),apiList<any>('/patient/payments',token)]).then(([fees,payments])=>setFallbackFinance({fees:fees.status==='fulfilled'?fees.value:[],payments:payments.status==='fulfilled'?payments.value:[]}))},[token])
  return <Shell onNavigate={onNavigate} profile={profile}>
    <section className="rounded-xl bg-gradient-to-r from-atlas-petrol to-atlas-teal p-7 text-white"><p className="text-sm font-bold uppercase text-white/70">{t('healthSpace')}</p><h1 className="mt-2 text-3xl font-black">{t('patientWelcome',{name:profile?.first_name??''})}</h1><p className="mt-2 text-white/75">{t('patientOverview')}</p></section>
    <PatientNotifications token={token} onNavigate={onNavigate}/>
    {data&&<><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Card label={t('nextAppointment')} value={data.next_appointment?`${data.next_appointment.date} · ${data.next_appointment.start_time.slice(0,5)}`:t('noResults')}/><Card label={t('totalAppointments')} value={data.total_appointments??0}/><Card label={t('completedVisits')} value={data.completed_visits??0}/><Card label={t('absences')} value={data.absences??0}/><Card label={t('recentDocuments')} value={data.recent_documents.length}/></div>
    <PatientFinancialSummary summary={data.financial_summary} dues={data.upcoming_due_dates??[]} items={data.financial_items??[]} fallbackFees={fallbackFinance.fees} fallbackPayments={fallbackFinance.payments} onNavigate={onNavigate}/>
    <div className="mt-6 grid gap-5 lg:grid-cols-2"><section className="rounded-xl border bg-white p-5"><h2 className="font-display text-xl font-bold">{t('recentAppointments')}</h2><div className="mt-4 space-y-3">{data.recent_appointments.map((item:any)=><div key={item.id} className="flex items-center justify-between gap-3 border-b pb-3 last:border-0"><div><b>{item.date} · {item.start_time.slice(0,5)}</b><p className="text-sm text-slate-500">{item.reason??''}</p></div><span className="rounded-full bg-atlas-mist px-3 py-1 text-xs font-bold uppercase text-atlas-teal">{item.status}</span></div>)}</div></section><section className="rounded-xl border bg-white p-5"><h2 className="font-display text-xl font-bold">{t('recentDocuments')}</h2><div className="mt-4 space-y-3">{data.recent_documents.map((item:any)=><button key={item.id} onClick={()=>onNavigate('/patient/documents')} className="flex w-full items-center justify-between gap-3 border-b pb-3 text-start last:border-0"><div><b>{item.title}</b><p className="text-sm text-slate-500">{item.document_type}</p></div><FileText size={18} className="text-atlas-teal"/></button>)}{!data.recent_documents.length&&<p className="text-sm text-slate-500">{t('noSharedDocument')}</p>}</div></section></div></>}
  </Shell>
}

const patientLocale=()=>({ar:'ar-MA',en:'en-MA',fr:'fr-MA'}[document.documentElement.lang]??'fr-MA')
const patientMoney=(value:number)=>new Intl.NumberFormat(patientLocale(),{style:'currency',currency:'MAD'}).format(Number(value??0))
function PatientFinancialSummary({summary,dues,items=[],fallbackFees=[],fallbackPayments=[],onNavigate}:{summary:any;dues:any[];items?:any[];fallbackFees?:any[];fallbackPayments?:any[];onNavigate:(path:string)=>void}){
  const[filter,setFilter]=useState<'all'|'paid'|'rap'|'upcoming'|'overdue'|null>(null)
  const[selected,setSelected]=useState<any|null>(null)
  if(!summary?.visible)return null
  const effectiveItems=items.length?items:fallbackFees.map(fee=>({...fee,cabinet_name:'Cabinet médical',doctor:null,appointments:[],visits:[],payments:fallbackPayments.filter(payment=>payment.fee_id===fee.id),dues:dues.filter(due=>due.fee_id===fee.id),documents:[]}))
  const filtered=effectiveItems.filter(item=>{
    if(filter==='paid')return item.paid_amount>0
    if(filter==='rap')return item.remaining_amount>0
    if(filter==='upcoming')return item.dues?.some((due:any)=>due.remaining_amount>0&&due.status!=='EN_RETARD')
    if(filter==='overdue')return item.dues?.some((due:any)=>due.remaining_amount>0&&due.status==='EN_RETARD')
    return true
  })
  const filterLabels={all:'Tous les honoraires',paid:'Honoraires avec paiements',rap:'Restes à payer',upcoming:'Échéances à venir',overdue:'Échéances en retard'}
  return <section className="mt-6 overflow-hidden rounded-2xl border border-atlas-line bg-white shadow-sm">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-atlas-line p-5"><div><p className="text-xs font-black uppercase tracking-wide text-atlas-teal">Situation financière</p><h2 className="mt-1 font-display text-xl font-bold">Paiements, RAP et échéances</h2><p className="mt-1 text-xs text-slate-500">Cliquez sur un montant pour consulter les honoraires, rendez-vous et documents associés.</p></div><button onClick={()=>onNavigate('/patient/payments')} className="rounded-lg bg-atlas-mist px-4 py-2 text-xs font-bold text-atlas-teal">Voir mes paiements</button></div>
    <div className="grid gap-px bg-atlas-line sm:grid-cols-2 xl:grid-cols-5"><FinancialMetric label="Total honoraires" value={patientMoney(summary.total_amount)} tone="slate" onClick={()=>setFilter('all')}/><FinancialMetric label="Total payé" value={patientMoney(summary.total_paid)} tone="green" onClick={()=>setFilter('paid')}/><FinancialMetric label="RAP" value={patientMoney(summary.remaining_amount)} tone="amber" onClick={()=>setFilter('rap')}/><FinancialMetric label="Échéances à venir" value={patientMoney(summary.upcoming_due_amount)} tone="blue" onClick={()=>setFilter('upcoming')}/><FinancialMetric label="Échéances en retard" value={patientMoney(summary.overdue_due_amount)} tone="red" onClick={()=>setFilter('overdue')}/></div>
    {filter&&<div className="border-t border-atlas-line bg-slate-50/60 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-wide text-atlas-teal">Détail sélectionné</p><h3 className="mt-1 font-display text-lg font-bold">{filterLabels[filter]}</h3></div><button type="button" onClick={()=>setFilter(null)} className="rounded-full bg-white p-2 text-slate-500 shadow-sm" aria-label="Fermer"><X size={18}/></button></div><div className="mt-4 grid gap-3 md:grid-cols-2">{filtered.map(item=><button type="button" key={item.id} onClick={()=>setSelected(item)} className="rounded-xl border border-atlas-line bg-white p-4 text-left shadow-sm hover:border-atlas-teal"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-wide text-atlas-teal">{item.cabinet_name}</p><b className="mt-1 block">{item.title}</b><p className="mt-1 text-xs text-slate-500">{item.doctor?.name??'Médecin du cabinet'}{item.doctor?.specialty?` · ${item.doctor.specialty}`:''}</p></div><Eye size={18} className="shrink-0 text-atlas-teal"/></div><div className="mt-3 grid grid-cols-3 gap-2 text-center text-xs"><span className="rounded-lg bg-slate-50 p-2">Total<br/><b>{patientMoney(item.amount)}</b></span><span className="rounded-lg bg-emerald-50 p-2 text-emerald-700">Payé<br/><b>{patientMoney(item.paid_amount)}</b></span><span className="rounded-lg bg-amber-50 p-2 text-amber-800">RAP<br/><b>{patientMoney(item.remaining_amount)}</b></span></div><p className="mt-3 text-xs font-bold text-atlas-teal">Voir rendez-vous, paiements et documents →</p></button>)}{!filtered.length&&<p className="rounded-xl border border-dashed border-atlas-line bg-white p-6 text-center text-sm text-slate-500 md:col-span-2">Aucun élément dans cette catégorie.</p>}</div></div>}
    {dues.length>0&&<div className="p-5"><div className="flex items-center justify-between"><b className="text-sm">Échéances ouvertes</b><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{summary.open_due_count} ouverte{summary.open_due_count>1?'s':''}</span></div><div className="mt-3 grid gap-3 md:grid-cols-2">{dues.map(item=><article key={item.id} className={`rounded-xl border p-4 ${item.status==='EN_RETARD'?'border-red-200 bg-red-50':'border-atlas-line bg-slate-50'}`}><div className="flex justify-between gap-3"><div><p className="text-xs font-black uppercase text-atlas-teal">{item.cabinet_name}</p><b className="mt-1 block">{new Date(`${item.due_date}T12:00:00`).toLocaleDateString(patientLocale(),{dateStyle:'long'})}</b></div><strong className={item.status==='EN_RETARD'?'text-red-700':'text-amber-700'}>{patientMoney(item.remaining_amount)}</strong></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-slate-200"><div className="h-full bg-atlas-teal" style={{width:`${Math.min(100,item.amount?item.paid_amount/item.amount*100:0)}%`}}/></div><p className="mt-2 text-[11px] font-semibold text-slate-500">{item.status.replaceAll('_',' ')}</p></article>)}</div></div>}
    {selected&&<PatientFinancialDetail item={selected} onClose={()=>setSelected(null)} onNavigate={onNavigate}/>}
  </section>
}
function FinancialMetric({label,value,tone,onClick}:{label:string;value:string;tone:'slate'|'green'|'amber'|'blue'|'red';onClick:()=>void}){const colors={slate:'text-atlas-petrol',green:'text-emerald-700',amber:'text-amber-700',blue:'text-blue-700',red:'text-red-700'};return <button type="button" onClick={onClick} className="group bg-white p-4 text-left hover:bg-slate-50 focus-visible:z-10"><div className="flex items-center justify-between gap-2"><p className="text-[11px] font-bold uppercase text-slate-400">{label}</p><Eye size={15} className="text-slate-300 group-hover:text-atlas-teal"/></div><b className={`mt-2 block text-lg ${colors[tone]}`}>{value}</b><span className="mt-2 block text-[10px] font-bold text-atlas-teal opacity-0 transition group-hover:opacity-100">Voir le détail</span></button>}
function PatientFinancialDetail({item,onClose,onNavigate}:{item:any;onClose:()=>void;onNavigate:(path:string)=>void}){
  const[selectedAppointment,setSelectedAppointment]=useState<any|null>(item.appointments?.[0]??null)
  const paymentMethods:Record<string,string>={cash:'Espèces',card:'Carte bancaire',transfer:'Virement',cheque:'Chèque'}
  return <div className="fixed inset-0 z-[90] grid place-items-center bg-slate-950/60 p-3 backdrop-blur-sm" role="dialog" aria-modal="true" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}>
    <section className="max-h-[94vh] w-full max-w-5xl overflow-y-auto rounded-2xl bg-white shadow-2xl">
      <header className="sticky top-0 z-10 flex items-start justify-between gap-4 border-b border-atlas-line bg-white p-5"><div><p className="text-xs font-black uppercase tracking-widest text-atlas-teal">{item.cabinet_name}</p><h2 className="mt-1 font-display text-2xl font-bold">{item.title}</h2><p className="mt-1 text-sm text-slate-500">{item.doctor?.name??'Médecin du cabinet'}{item.doctor?.specialty?` · ${item.doctor.specialty}`:''}</p></div><button type="button" onClick={onClose} className="rounded-full bg-slate-100 p-2 text-slate-500" aria-label="Fermer"><X size={20}/></button></header>
      <div className="p-5">
        <div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-4"><p className="text-[10px] font-black uppercase text-slate-400">Montant total</p><b className="mt-2 block text-xl">{patientMoney(item.amount)}</b></div><div className="rounded-xl bg-emerald-50 p-4"><p className="text-[10px] font-black uppercase text-emerald-600">Total payé</p><b className="mt-2 block text-xl text-emerald-700">{patientMoney(item.paid_amount)}</b></div><div className="rounded-xl bg-amber-50 p-4"><p className="text-[10px] font-black uppercase text-amber-600">Reste à payer</p><b className="mt-2 block text-xl text-amber-800">{patientMoney(item.remaining_amount)}</b></div></div>
        <div className="mt-5 grid gap-5 lg:grid-cols-2">
          <section className="rounded-xl border border-atlas-line p-4"><div className="flex items-center justify-between"><h3 className="font-display text-lg font-bold">Rendez-vous et visites</h3><span className="rounded-full bg-atlas-mist px-3 py-1 text-xs font-bold text-atlas-teal">{(item.appointments?.length??0)+(item.visits?.length??0)}</span></div><div className="mt-3 space-y-2">{item.appointments?.map((appointment:any)=><button type="button" key={appointment.id} onClick={()=>setSelectedAppointment(appointment)} className={`w-full rounded-lg border p-3 text-left ${selectedAppointment?.id===appointment.id?'border-atlas-teal bg-atlas-mist':'border-atlas-line bg-slate-50 hover:border-atlas-teal'}`}><div className="flex items-center justify-between gap-3"><div><b className="text-sm">{new Date(`${appointment.date}T12:00:00`).toLocaleDateString(patientLocale(),{dateStyle:'long'})}</b><p className="mt-1 text-xs text-slate-500">{appointment.start_time.slice(0,5)}–{appointment.end_time.slice(0,5)} · {appointment.reason??'Consultation'}</p></div><ChevronRight size={17} className="text-atlas-teal"/></div></button>)}{item.visits?.map((visit:any)=><div key={visit.id} className="rounded-lg border border-atlas-line bg-slate-50 p-3"><b className="text-sm">Visite du {new Date(`${visit.visit_date}T12:00:00`).toLocaleDateString(patientLocale())}</b><p className="mt-1 text-xs text-slate-500">{visit.reason??'Consultation'} · {visit.attendance_status==='absent'?'Absent':'Présent'}</p></div>)}{!item.appointments?.length&&!item.visits?.length&&<p className="rounded-lg bg-slate-50 p-4 text-sm text-slate-500">Aucun rendez-vous lié.</p>}</div>{selectedAppointment&&<div className="mt-3 rounded-lg border border-atlas-teal/20 bg-atlas-mist/60 p-3"><p className="text-[10px] font-black uppercase text-atlas-teal">Rendez-vous sélectionné</p><b className="mt-1 block text-sm">{selectedAppointment.doctor_name??item.doctor?.name??'Médecin du cabinet'}</b><p className="mt-1 text-xs text-slate-600">{selectedAppointment.reason??'Consultation'} · Statut : {String(selectedAppointment.status).replaceAll('_',' ')}</p></div>}</section>
          <section className="rounded-xl border border-atlas-line p-4"><div className="flex items-center justify-between"><h3 className="font-display text-lg font-bold">Historique des paiements</h3><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">{item.payments?.length??0}</span></div><div className="mt-3 space-y-2">{item.payments?.map((payment:any,index:number)=><div key={payment.id} className="flex items-center gap-3 rounded-lg border border-atlas-line bg-slate-50 p-3"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-atlas-teal text-xs font-black text-white">{index+1}</span><div className="min-w-0 flex-1"><div className="flex justify-between gap-3"><b className="text-sm text-emerald-700">{patientMoney(payment.amount)}</b><span className="text-[10px] font-bold text-slate-400">{new Date(payment.paid_at).toLocaleDateString(patientLocale())}</span></div><p className="mt-1 text-xs text-slate-500">{paymentMethods[payment.method]??payment.method}{payment.reference?` · ${payment.reference}`:''}</p></div></div>)}{!item.payments?.length&&<p className="rounded-lg bg-slate-50 p-4 text-sm text-slate-500">Aucun paiement enregistré.</p>}</div></section>
          <section className="rounded-xl border border-atlas-line p-4"><div className="flex items-center justify-between"><h3 className="font-display text-lg font-bold">Échéances</h3><span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-800">{item.dues?.length??0}</span></div><div className="mt-3 space-y-2">{item.dues?.map((due:any)=><div key={due.id} className={`rounded-lg border p-3 ${due.status==='EN_RETARD'?'border-red-200 bg-red-50':'border-atlas-line bg-slate-50'}`}><div className="flex justify-between gap-3"><b className="text-sm">{new Date(`${due.due_date}T12:00:00`).toLocaleDateString(patientLocale(),{dateStyle:'long'})}</b><strong className={due.status==='EN_RETARD'?'text-red-700':'text-amber-700'}>{patientMoney(due.remaining_amount)}</strong></div><p className="mt-1 text-[10px] font-bold uppercase text-slate-500">{String(due.status).replaceAll('_',' ')}</p></div>)}{!item.dues?.length&&<p className="rounded-lg bg-slate-50 p-4 text-sm text-slate-500">Aucune échéance liée.</p>}</div></section>
          <section className="rounded-xl border border-atlas-line p-4"><div className="flex items-center justify-between"><h3 className="font-display text-lg font-bold">Documents partagés</h3><span className="rounded-full bg-violet-50 px-3 py-1 text-xs font-bold text-violet-700">{item.documents?.length??0}</span></div><div className="mt-3 space-y-2">{item.documents?.map((document:any)=><button type="button" key={document.id} onClick={()=>onNavigate('/patient/documents')} className="flex w-full items-center justify-between gap-3 rounded-lg border border-atlas-line bg-slate-50 p-3 text-left hover:border-atlas-teal"><div><b className="text-sm">{document.title}</b><p className="mt-1 text-xs text-slate-500">{document.document_type}{document.document_date?` · ${new Date(`${document.document_date}T12:00:00`).toLocaleDateString(patientLocale())}`:''}</p></div><FileText size={17} className="text-atlas-teal"/></button>)}{!item.documents?.length&&<p className="rounded-lg bg-slate-50 p-4 text-sm text-slate-500">Aucun document partagé pour ce dossier.</p>}</div></section>
        </div>
      </div>
    </section>
  </div>
}
const Card=({label,value}:{label:string;value:string|number})=><div className="rounded-xl border bg-white p-5"><p className="text-sm font-bold text-slate-500">{label}</p><p className="mt-2 text-xl font-black">{value}</p></div>

type PatientWhatsAppConsent={status:'pending'|'accepted'|'refused'|'withdrawn';phone_number:string|null;preferred_language:'fr'|'ar';opt_in_at:string|null;opt_out_at:string|null}

export function PatientCommunicationPreferences({onNavigate}:{onNavigate:(p:string)=>void}){
  const{token,profile}=useProfile()
  const[consent,setConsent]=useState<PatientWhatsAppConsent|null>(null)
  const[phone,setPhone]=useState('')
  const[language,setLanguage]=useState<'fr'|'ar'>('fr')
  const[busy,setBusy]=useState(false)
  const[feedback,setFeedback]=useState<{kind:'success'|'error';text:string}|null>(null)
  const load=useCallback(async()=>{const value=await apiGet<PatientWhatsAppConsent>('/patient/me/whatsapp-consent',token);setConsent(value);setPhone(value.phone_number??profile?.phone??'');setLanguage(value.preferred_language)},[profile?.phone,token])
  useEffect(()=>{if(token)void load().catch(reason=>setFeedback({kind:'error',text:reason instanceof Error?reason.message:'Préférences indisponibles.'}))},[load,token])
  async function decide(action:'accept'|'refuse'|'withdraw'){
    setBusy(true);setFeedback(null)
    try{
      if(action==='accept')await apiCreate('/patient/me/whatsapp-consent/accept',token,{phone_number:phone,accepted:true,preferred_language:language})
      if(action==='refuse')await apiCreate('/patient/me/whatsapp-consent/refuse',token,{reason:'Décision enregistrée depuis l’espace patient.'})
      if(action==='withdraw')await apiCreate('/patient/me/whatsapp-consent/withdraw',token,{reason:'Consentement retiré depuis l’espace patient.'})
      await load()
      setFeedback({kind:'success',text:action==='accept'?'Votre consentement WhatsApp a été enregistré.':action==='refuse'?'Votre refus a été enregistré.':'Votre consentement WhatsApp a été retiré.'})
    }catch(reason){setFeedback({kind:'error',text:reason instanceof Error?reason.message:'Modification impossible.'})}
    finally{setBusy(false)}
  }
  async function savePreferences(){
    setBusy(true);setFeedback(null)
    try{await apiPatch('/patient/me/whatsapp-consent/preferences',token,{phone_number:phone,preferred_language:language});await load();setFeedback({kind:'success',text:'Vos préférences ont été mises à jour.'})}
    catch(reason){setFeedback({kind:'error',text:reason instanceof Error?reason.message:'Modification impossible.'})}
    finally{setBusy(false)}
  }
  const status=consent?.status??'pending'
  const labels={pending:'Décision en attente',accepted:'Communications autorisées',refused:'Communications refusées',withdrawn:'Consentement retiré'}
  const tones={pending:'bg-slate-100 text-slate-700',accepted:'bg-emerald-100 text-emerald-800',refused:'bg-amber-100 text-amber-800',withdrawn:'bg-red-100 text-red-700'}
  return <Shell onNavigate={onNavigate} profile={profile}><Header title="communicationPreferences" subtitle="communicationPreferencesSubtitle"/>
    <section className="mt-6 overflow-hidden rounded-2xl border border-atlas-line bg-white shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-4 border-b border-atlas-line p-6"><div className="flex items-start gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-atlas-mist text-atlas-teal"><MessageCircle size={23}/></span><div><h2 className="font-display text-2xl font-bold">Communications WhatsApp</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-500">Le cabinet peut vous envoyer des rappels de rendez-vous, des informations administratives ou des relances. Votre choix peut être modifié à tout moment.</p></div></div><span className={`rounded-full px-4 py-2 text-xs font-black ${tones[status]}`}>{labels[status]}</span></div>
      <div className="grid gap-5 p-6 md:grid-cols-2"><label className="text-sm font-bold">Mon numéro WhatsApp<input type="tel" value={phone} onChange={event=>setPhone(event.target.value)} placeholder="+212 6…" className="mt-2 w-full rounded-lg border border-atlas-line px-4 py-3 font-normal outline-none focus:border-atlas-teal"/></label><label className="text-sm font-bold">Langue des messages<select value={language} onChange={event=>setLanguage(event.target.value as 'fr'|'ar')} className="mt-2 w-full rounded-lg border border-atlas-line bg-white px-4 py-3 font-normal outline-none focus:border-atlas-teal"><option value="fr">Français</option><option value="ar">Arabe</option></select></label></div>
      <div className="border-t border-atlas-line bg-slate-50 p-6"><p className="text-sm font-bold text-slate-800">Votre décision</p><p className="mt-1 text-xs leading-5 text-slate-500">Vous pouvez autoriser, refuser ou retirer les communications WhatsApp à tout moment.</p>{feedback&&<p role="status" className={`mt-4 rounded-lg p-3 text-sm font-bold ${feedback.kind==='success'?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'}`}>{feedback.text}</p>}<div className="mt-5 flex flex-wrap gap-3">{status!=='accepted'&&<button disabled={busy||!phone} onClick={()=>void decide('accept')} className="rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white disabled:opacity-40">J’accepte les communications WhatsApp</button>}{status!=='refused'&&status!=='accepted'&&<button disabled={busy} onClick={()=>void decide('refuse')} className="rounded-lg border border-amber-300 bg-white px-5 py-3 font-bold text-amber-800 disabled:opacity-40">Je refuse</button>}{status==='accepted'&&<><button disabled={busy||!phone} onClick={()=>void savePreferences()} className="rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white disabled:opacity-40">Enregistrer mes préférences</button><button disabled={busy} onClick={()=>void decide('withdraw')} className="rounded-lg border border-red-200 bg-white px-5 py-3 font-bold text-red-700 disabled:opacity-40">Retirer mon consentement</button></>}</div></div>
    </section>
  </Shell>
}

function PatientNotifications({token,onNavigate}:{token:string;onNavigate:(path:string)=>void}){
  const[rows,setRows]=useState<Array<{id:string;type:string;title:string;message:string;resource_id:string|null;read_at:string|null;created_at:string}>>([])
  const[expanded,setExpanded]=useState(false)
  useEffect(()=>{if(token)apiList<any>('/patient/notifications',token).then(setRows).catch(()=>setRows([]))},[token])
  if(!rows.length)return null
  const unread=rows.filter(item=>!item.read_at).length
  const notificationStyle=(type:string)=>type==='PAYMENT_REMINDER'
    ?'border-amber-200 bg-amber-50/55 hover:border-amber-400'
    :type==='CNSS_STATUS'
      ?'border-blue-200 bg-blue-50/55 hover:border-blue-400'
      :type.includes('APPOINTMENT')
        ?'border-emerald-200 bg-emerald-50/55 hover:border-emerald-400'
        :type.includes('DOCUMENT')||type.includes('PRESCRIPTION')
          ?'border-violet-200 bg-violet-50/55 hover:border-violet-400'
          :'border-slate-200 bg-slate-50/55 hover:border-atlas-teal'
  async function open(item:typeof rows[number]){if(!item.read_at){const result=await apiPatch<{read_at:string}>(`/patient/notifications/${item.id}/read`,token,{});setRows(current=>current.map(row=>row.id===item.id?{...row,read_at:result.read_at}:row))}if(item.type==='PAYMENT_REMINDER')onNavigate('/patient/payments');if(item.type==='PLATFORM_EVENT'&&item.resource_id)onNavigate(`/evenements/${item.resource_id}`)}
  async function readAll(){if(!unread)return;const result=await apiPatch<{read_at:string}>('/patient/notifications/read-all',token,{});setRows(current=>current.map(row=>({...row,read_at:row.read_at??result.read_at})))}
  return <section className="mt-6 rounded-xl border border-atlas-line bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-atlas-teal"><Bell size={15}/>Notifications du cabinet</p><h2 className="mt-1 font-display text-xl font-bold">Messages importants</h2></div><div className="flex items-center gap-2"><span className="rounded-full bg-atlas-mist px-3 py-1 text-xs font-black text-atlas-teal">{unread} nouvelle(s)</span>{unread>0&&<button onClick={()=>void readAll()} className="inline-flex items-center gap-1 rounded-lg border border-atlas-line bg-white px-3 py-2 text-xs font-bold text-atlas-teal hover:bg-atlas-mist"><CheckCheck size={14}/>Tout marquer comme lu</button>}</div></div><div className="mt-4 space-y-2">{rows.slice(0,expanded?rows.length:3).map(item=><button key={item.id} onClick={()=>void open(item)} className={`block w-full rounded-lg border p-4 text-left transition ${notificationStyle(item.type)} ${item.read_at?'opacity-65':''}`}><div className="flex flex-wrap justify-between gap-2"><span className="flex items-center gap-2"><b>{item.title}</b>{!item.read_at&&<span className="h-2 w-2 rounded-full bg-atlas-teal"/>}</span><span className="text-xs text-slate-400">{new Date(item.created_at).toLocaleString(patientLocale())}</span></div><p className="mt-2 text-sm leading-6 text-slate-600">{item.message}</p>{item.type==='PAYMENT_REMINDER'&&<span className="mt-3 inline-flex rounded-lg bg-white/80 px-3 py-2 text-xs font-bold text-atlas-teal">Voir mes paiements</span>}</button>)}</div>{rows.length>3&&<div className="mt-4 flex justify-center"><button type="button" onClick={()=>setExpanded(value=>!value)} className="rounded-lg border border-atlas-teal/25 bg-atlas-mist px-5 py-2.5 text-sm font-bold text-atlas-teal transition hover:border-atlas-teal hover:bg-emerald-50">{expanded?'Voir moins':`Voir plus (${rows.length-3})`}</button></div>}</section>
}

function PatientQrButton({appointment}:{appointment:PatientAppointment}){
  const token=getSession()?.accessToken??''
  const[open,setOpen]=useState(false)
  const[data,setData]=useState<AppointmentQr|null>(null)
  const[error,setError]=useState('')
  const[loading,setLoading]=useState(false)
  async function show(){
    setOpen(true);setError('')
    if(data)return
    setLoading(true)
    try{setData(await apiGet<AppointmentQr>(`/patient/appointments/${appointment.id}/qr`,token))}
    catch(reason){setError(reason instanceof Error?reason.message:'QR indisponible.')}
    finally{setLoading(false)}
  }
  return <>
    <button type="button" onClick={()=>void show()} className="inline-flex items-center gap-2 rounded-lg border border-atlas-teal/25 bg-white px-4 py-2 text-sm font-bold text-atlas-teal transition hover:bg-atlas-mist"><QrCode size={17}/>Mon QR</button>
    {open&&<div className="fixed inset-0 z-[70] grid place-items-center bg-slate-950/65 p-4" onMouseDown={event=>{if(event.target===event.currentTarget)setOpen(false)}}>
      <section role="dialog" aria-modal="true" aria-labelledby="appointment-qr-title" className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl">
        <div className="flex items-start justify-between gap-4 border-b border-atlas-line px-5 py-4"><div><p className="text-[10px] font-black uppercase tracking-[.16em] text-atlas-teal">Accès au rendez-vous</p><h2 id="appointment-qr-title" className="mt-1 font-display text-xl font-bold">Mon QR de présence</h2></div><button type="button" onClick={()=>setOpen(false)} aria-label="Fermer" className="rounded-full bg-slate-100 p-2"><X size={19}/></button></div>
        <div className="p-5">
          {loading&&<div className="grid min-h-72 place-items-center rounded-xl bg-slate-50 font-bold text-slate-400">Génération du QR…</div>}
          {error&&<p className="rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700">{error}</p>}
          {data&&<><div className={`mx-auto w-fit rounded-2xl border-4 bg-white p-3 shadow-sm ${data.active?'border-atlas-mist':'border-slate-200 opacity-50'}`} dangerouslySetInnerHTML={{__html:data.qr_svg}}/><div className="mt-4 rounded-xl bg-atlas-mist/60 p-4 text-center"><b className="block">{new Date(`${data.date}T12:00:00`).toLocaleDateString(patientLocale(),{dateStyle:'full'})}</b><p className="mt-1 text-sm font-semibold text-atlas-teal">{data.start_time.slice(0,5)} – {data.end_time.slice(0,5)}</p><p className="mt-1 text-xs text-slate-500">{data.doctor_name??'Médecin du cabinet'}</p></div><details className="mt-3 rounded-lg border border-atlas-line bg-slate-50 p-3"><summary className="cursor-pointer text-center text-xs font-bold text-slate-600">Afficher le code de secours</summary><code className="mt-2 block break-all text-center text-[10px] text-slate-500">{data.qr_payload}</code></details>{data.scanned_at?<p className="mt-3 rounded-lg bg-emerald-50 p-3 text-center text-sm font-bold text-emerald-700">Présence confirmée le {new Date(data.scanned_at).toLocaleString(patientLocale())}</p>:data.active?<p className="mt-3 text-center text-xs leading-5 text-slate-500">Présentez ce QR au médecin. Il confirme votre arrivée et conserve l’heure réelle du scan.</p>:<p className="mt-3 rounded-lg bg-slate-100 p-3 text-center text-sm font-bold text-slate-600">Ce QR n’est plus actif.</p>}</>}
        </div>
      </section>
    </div>}
  </>
}

export function PatientAppointments({onNavigate,request=false}:{onNavigate:(p:string)=>void;request?:boolean}) {
  const{t,i18n}=useTranslation()
  const {token,profile}=useProfile()
  const [rows,setRows]=useState<PatientAppointment[]>([])
  const [selectedAppointment,setSelectedAppointment]=useState<PatientAppointment|null>(null)
  const [cancelTarget,setCancelTarget]=useState<PatientAppointment|null>(null)
  const [cancelBusy,setCancelBusy]=useState(false)
  const [cancelError,setCancelError]=useState('')
  const [doctors,setDoctors]=useState<PublicDoctor[]>([])
  const [availability,setAvailability]=useState<AvailabilityDay[]>([])
  const [availabilityLoading,setAvailabilityLoading]=useState(false)
  const [calendarPage,setCalendarPage]=useState(0)
  const [appointmentView,setAppointmentView]=useState<'calendar'|'list'>('calendar')
  const [msg,setMsg]=useState('')
  const [form,setForm]=useState({doctor_id:sessionStorage.getItem('fadaa_selected_doctor')??'',date:'',start_time:'',end_time:'',reason:''})
  const load=useCallback(()=>apiList<PatientAppointment>('/patient/appointments',token).then(setRows),[token])
  useEffect(()=>{load()},[load])
  useEffect(()=>{fetch(`${import.meta.env.VITE_API_URL??''}/api/public/doctors`).then(response=>response.json()).then(setDoctors).catch(()=>setDoctors([]))},[])
  useEffect(()=>{
    if(!form.doctor_id){setAvailability([]);return}
    setCalendarPage(0)
    setAvailabilityLoading(true);setMsg('')
    fetch(`${import.meta.env.VITE_API_URL??''}/api/public/doctors/${form.doctor_id}/availability`)
      .then(response=>{if(!response.ok)throw new Error('Créneaux indisponibles.');return response.json()})
      .then((days:AvailabilityDay[])=>setAvailability(days.filter(day=>day.slots.length>0)))
      .catch(error=>{setAvailability([]);setMsg(error instanceof Error?error.message:'Créneaux indisponibles.')})
      .finally(()=>setAvailabilityLoading(false))
  },[form.doctor_id])
  async function submit(event:FormEvent){
    event.preventDefault()
    try{
      await apiCreate('/patient/appointments/request',token,form)
      setMsg('Votre demande a été transmise au cabinet sélectionné.')
      setForm(current=>({...current,date:'',start_time:'',end_time:'',reason:''}))
      sessionStorage.removeItem('fadaa_selected_doctor')
      await load()
    }catch(error){setMsg(error instanceof Error?error.message:'Demande impossible.')}
  }
  async function action(id:string,kind:'confirm'|'cancel'){await apiUpdate(`/patient/appointments/${id}/${kind}`,token,{});await load()}
  async function confirmCancellation(){
    if(!cancelTarget)return
    setCancelBusy(true);setCancelError('')
    try{await action(cancelTarget.id,'cancel');setCancelTarget(null)}
    catch(error){setCancelError(error instanceof Error?error.message:'Annulation impossible.')}
    finally{setCancelBusy(false)}
  }
  const now=Date.now()
  const terminalStatuses=['completed','cancelled','rejected','absent']
  const upcoming=rows.filter(item=>new Date(`${item.date}T${item.end_time}`).getTime()>=now&&!terminalStatuses.includes(item.status)).sort((a,b)=>`${a.date}${a.start_time}`.localeCompare(`${b.date}${b.start_time}`))
  const history=rows.filter(item=>new Date(`${item.date}T${item.end_time}`).getTime()<now||terminalStatuses.includes(item.status)).sort((a,b)=>`${b.date}${b.start_time}`.localeCompare(`${a.date}${a.start_time}`))
  function appointmentCard(item:PatientAppointment){
    const status=appointmentStatuses[item.status]??{label:item.status,style:'bg-slate-100 text-slate-700'}
    return <article key={item.id} className="rounded-xl border border-atlas-line bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wide text-atlas-teal">{item.cabinet_name??profile?.cabinet_name??'Cabinet médical'}</p><h3 className="mt-1 text-lg font-bold">{item.doctor_name??'Médecin du cabinet'}</h3><p className="text-sm text-slate-500">{item.doctor_specialty??'Médecine générale'}</p></div><span className={`rounded-full px-3 py-1 text-xs font-bold ${status.style}`}>{status.label}</span></div><div className="mt-4 grid gap-2 text-sm text-slate-600 sm:grid-cols-2"><p className="flex items-center gap-2"><CalendarDays size={16} className="text-atlas-teal"/>{new Date(`${item.date}T12:00:00`).toLocaleDateString(patientLocale(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p><p className="flex items-center gap-2"><Clock size={16} className="text-atlas-teal"/>{item.start_time.slice(0,5)} – {item.end_time.slice(0,5)}</p><p className="flex items-center gap-2 sm:col-span-2"><MapPin size={16} className="shrink-0 text-atlas-teal"/>{[item.cabinet_address,item.cabinet_city].filter(Boolean).join(', ')||'Adresse non renseignée'}</p></div><p className="mt-4 rounded-lg bg-atlas-cloud p-3 text-sm"><span className="font-bold">Motif :</span> {item.reason??'Non renseigné'}</p><div className="mt-4 flex flex-wrap items-center gap-3"><button type="button" onClick={()=>setSelectedAppointment(item)} className="inline-flex items-center gap-1 rounded-lg bg-atlas-mist px-4 py-2 text-sm font-bold text-atlas-teal">Voir les détails <ChevronRight size={16}/></button>{!terminalStatuses.includes(item.status)&&<PatientQrButton appointment={item}/>} {profile?.settings.patient_can_confirm_appointment&&item.status==='planned'&&<button onClick={()=>action(item.id,'confirm')} className="text-sm font-bold text-emerald-700">Confirmer</button>}{profile?.settings.patient_can_cancel_appointment&&!terminalStatuses.includes(item.status)&&<button onClick={()=>{setCancelError('');setCancelTarget(item)}} className="text-sm font-bold text-red-600">Annuler</button>}</div></article>
  }
  return <Shell onNavigate={onNavigate} profile={profile}>
    {request?<Header title="requestAppointment" subtitle="requestAppointmentSubtitle"/>:<div className="flex flex-wrap items-end justify-between gap-4"><Header title="myAppointments" subtitle="appointmentsSubtitle"/>{profile?.settings.patient_can_request_appointment&&<button type="button" onClick={()=>onNavigate('/patient/appointments/request')} className="inline-flex items-center gap-2 rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white shadow-sm hover:bg-atlas-petrol"><Plus size={18}/>Prendre rendez-vous</button>}</div>}
    {request&&profile?.settings.patient_can_request_appointment&&<form onSubmit={submit} className="mt-6 overflow-hidden rounded-2xl border border-atlas-line bg-white shadow-sm">
      <div className="border-b border-atlas-line bg-gradient-to-r from-atlas-petrol to-atlas-teal px-5 py-4 text-white"><p className="text-[10px] font-black uppercase tracking-[.18em] text-white/70">Nouvelle réservation</p><h2 className="mt-1 font-display text-xl font-bold">Choisissez votre médecin et votre créneau</h2><p className="mt-1 text-xs text-white/75">Le rendez-vous sera automatiquement rattaché au cabinet et au médecin sélectionnés.</p></div>
      <div className="grid gap-5 p-4 lg:grid-cols-[280px_1fr] lg:p-5">
        <aside className="space-y-5">
          <label className="block"><span className="text-sm font-bold">Cabinet et médecin *</span><select required value={form.doctor_id} onChange={event=>{setForm({...form,doctor_id:event.target.value,date:'',start_time:'',end_time:''})}} className="mt-2 w-full rounded-xl border border-atlas-line bg-white p-3 outline-none focus:border-atlas-teal"><option value="">Sélectionner un médecin</option>{doctors.map(doctor=><option key={doctor.id} value={doctor.id}>{doctor.cabinet} · {doctor.name} · {doctor.specialty} · {doctor.city}</option>)}</select></label>
          {form.doctor_id&&<div className="space-y-3"><div className="rounded-xl bg-atlas-mist/60 p-4"><p className="text-xs font-black uppercase text-atlas-teal">Médecin sélectionné</p><b className="mt-2 block">{doctors.find(item=>item.id===form.doctor_id)?.name}</b><p className="mt-1 text-sm text-slate-600">{doctors.find(item=>item.id===form.doctor_id)?.specialty}</p><p className="mt-1 text-xs text-slate-500">{doctors.find(item=>item.id===form.doctor_id)?.cabinet} · {doctors.find(item=>item.id===form.doctor_id)?.city}</p></div><CabinetLocationMap compact address={doctors.find(item=>item.id===form.doctor_id)?.address} city={doctors.find(item=>item.id===form.doctor_id)?.city} cabinetName={doctors.find(item=>item.id===form.doctor_id)?.cabinet} doctorName={doctors.find(item=>item.id===form.doctor_id)?.name}/></div>}
          <label className="block"><span className="text-sm font-bold">Motif de consultation</span><textarea value={form.reason} onChange={event=>setForm({...form,reason:event.target.value})} className="mt-2 min-h-20 w-full rounded-xl border border-atlas-line p-3 text-sm outline-none focus:border-atlas-teal" placeholder="Décrivez brièvement votre besoin…"/></label>
        </aside>
        <section>
          <div className="flex items-center justify-between"><div><p className="text-xs font-black uppercase tracking-wide text-atlas-teal">Agenda du médecin</p><h3 className="mt-1 font-display text-xl font-bold">Créneaux disponibles</h3></div>{form.date&&<span className="rounded-full bg-atlas-mist px-3 py-1 text-xs font-bold text-atlas-teal">{new Date(`${form.date}T12:00:00`).toLocaleDateString(patientLocale(),{day:'numeric',month:'short'})}</span>}</div>
          {!form.doctor_id?<div className="mt-5 grid min-h-72 place-items-center rounded-xl border border-dashed border-atlas-line bg-slate-50 p-8 text-center"><div><Stethoscope className="mx-auto text-slate-300" size={38}/><p className="mt-3 font-bold text-slate-600">Sélectionnez d’abord un médecin</p><p className="mt-1 text-sm text-slate-400">Son agenda et ses disponibilités apparaîtront ici.</p></div></div>:availabilityLoading?<div className="mt-5 grid min-h-72 place-items-center rounded-xl bg-slate-50 font-bold text-slate-400">Chargement de l’agenda…</div>:<PatientBookingCalendar availability={availability} appointments={rows.filter(item=>item.doctor_id===form.doctor_id&&!terminalStatuses.includes(item.status))} page={calendarPage} selectedDate={form.date} selectedTime={form.start_time} onPage={setCalendarPage} onSelect={(date,start_time,end_time)=>setForm({...form,date,start_time,end_time})}/>}
        </section>
      </div>
      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-atlas-line bg-slate-50 px-4 py-3"><button type="button" onClick={()=>onNavigate('/patient/appointments')} className="rounded-lg border border-atlas-line bg-white px-4 py-2.5 text-xs font-bold">Retour à mes rendez-vous</button><button disabled={!form.doctor_id||!form.date||!form.start_time} className="rounded-lg bg-atlas-teal px-5 py-2.5 text-xs font-bold text-white shadow-sm hover:bg-atlas-petrol disabled:cursor-not-allowed disabled:opacity-40">Confirmer la demande{form.start_time?` · ${form.start_time}`:''}</button></div>
      {msg&&<p className="border-t border-atlas-line bg-white p-4 text-center text-sm font-semibold text-atlas-teal">{msg}</p>}
    </form>}
    {!request&&<><div className="mt-7 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-display text-2xl font-bold">Mon agenda santé</h2><p className="mt-1 text-sm text-slate-500">Consultez vos rendez-vous passés et à venir dans un seul calendrier.</p></div><div className="inline-flex rounded-xl border border-atlas-line bg-white p-1 shadow-sm" aria-label="Mode d’affichage"><button type="button" onClick={()=>setAppointmentView('calendar')} className={`inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-bold ${appointmentView==='calendar'?'bg-atlas-teal text-white':'text-slate-600 hover:bg-slate-50'}`}><CalendarDays size={16}/>Agenda</button><button type="button" onClick={()=>setAppointmentView('list')} className={`inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-bold ${appointmentView==='list'?'bg-atlas-teal text-white':'text-slate-600 hover:bg-slate-50'}`}><List size={16}/>Liste</button></div></div>{appointmentView==='calendar'?<PatientAppointmentCalendar appointments={rows} upcoming={upcoming} onSelect={setSelectedAppointment}/>:<><section className="mt-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-xl font-bold">Prochains rendez-vous</h2><span className="rounded-full bg-atlas-mist px-3 py-1 text-xs font-bold text-atlas-teal">{upcoming.length}</span></div><div className="grid gap-4 lg:grid-cols-2">{upcoming.map(appointmentCard)}{!upcoming.length&&<p className="rounded-xl border border-atlas-line bg-white p-8 text-center text-slate-500 lg:col-span-2">Aucun rendez-vous à venir.</p>}</div></section><section className="mt-8"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-xl font-bold">Historique</h2><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-600">{history.length}</span></div><div className="grid gap-4 lg:grid-cols-2">{history.map(appointmentCard)}{!history.length&&<p className="rounded-xl border border-atlas-line bg-white p-8 text-center text-slate-500 lg:col-span-2">Aucun ancien rendez-vous.</p>}</div></section></>}</>}
    {selectedAppointment&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/55 p-4" onMouseDown={event=>{if(event.target===event.currentTarget)setSelectedAppointment(null)}}><section className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-widest text-atlas-teal">Détail du rendez-vous</p><h2 className="mt-1 font-display text-2xl font-bold">{selectedAppointment.cabinet_name??profile?.cabinet_name}</h2></div><button type="button" onClick={()=>setSelectedAppointment(null)} aria-label="Fermer" className="rounded-full bg-slate-100 p-2"><X size={20}/></button></div><div className="mt-6 space-y-4"><div className="flex items-start gap-3"><Stethoscope className="mt-0.5 text-atlas-teal" size={20}/><div><b>{selectedAppointment.doctor_name??'Médecin du cabinet'}</b><p className="text-sm text-slate-500">{selectedAppointment.doctor_specialty??'Spécialité non renseignée'}</p></div></div><div className="flex items-start gap-3"><CalendarDays className="mt-0.5 text-atlas-teal" size={20}/><div><b>{new Date(`${selectedAppointment.date}T12:00:00`).toLocaleDateString(patientLocale(),{dateStyle:'full'})}</b><p className="text-sm text-slate-500">De {selectedAppointment.start_time.slice(0,5)} à {selectedAppointment.end_time.slice(0,5)}</p></div></div><div className="flex items-start gap-3"><MapPin className="mt-0.5 text-atlas-teal" size={20}/><div><b>Adresse du cabinet</b><p className="text-sm text-slate-500">{[selectedAppointment.cabinet_address,selectedAppointment.cabinet_city].filter(Boolean).join(', ')||'Non renseignée'}</p></div></div><CabinetLocationMap address={selectedAppointment.cabinet_address} city={selectedAppointment.cabinet_city} cabinetName={selectedAppointment.cabinet_name??profile?.cabinet_name} doctorName={selectedAppointment.doctor_name}/><div className="flex items-start gap-3"><Phone className="mt-0.5 text-atlas-teal" size={20}/><div><b>Téléphone du cabinet</b><p className="text-sm text-slate-500">{selectedAppointment.cabinet_phone??'Non renseigné'}</p></div></div><div className="rounded-lg bg-atlas-cloud p-4"><b>Motif de consultation</b><p className="mt-1 text-sm text-slate-600">{selectedAppointment.reason??'Non renseigné'}</p></div></div></section></div>}
    {cancelTarget&&<div className="fixed inset-0 z-[60] grid place-items-center bg-slate-950/60 p-4" onMouseDown={event=>{if(event.target===event.currentTarget&&!cancelBusy)setCancelTarget(null)}}><section role="alertdialog" aria-modal="true" aria-labelledby="cancel-title" className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-red-50 text-red-600"><X size={28}/></div><h2 id="cancel-title" className="mt-4 text-center font-display text-2xl font-bold">Annuler ce rendez-vous ?</h2><p className="mt-2 text-center text-sm leading-6 text-slate-600"><Trans i18nKey="cancelAppointmentPrompt" values={{doctor:cancelTarget.doctor_name??t('practiceDoctor'),date:new Date(`${cancelTarget.date}T12:00:00`).toLocaleDateString(i18n.resolvedLanguage??i18n.language,{dateStyle:'long'}),time:cancelTarget.start_time.slice(0,5)}} components={{strong:<b/>}}/></p><p className="mt-3 rounded-lg bg-red-50 p-3 text-center text-sm font-semibold text-red-700">Cette action modifiera immédiatement le statut du rendez-vous.</p>{cancelError&&<p className="mt-3 rounded-lg bg-red-50 p-3 text-sm font-bold text-red-700">{cancelError}</p>}<div className="mt-6 grid gap-3 sm:grid-cols-2"><button type="button" disabled={cancelBusy} onClick={()=>setCancelTarget(null)} className="rounded-lg border border-atlas-line px-4 py-3 font-bold text-slate-700 disabled:opacity-50">Garder le rendez-vous</button><button type="button" disabled={cancelBusy} onClick={()=>void confirmCancellation()} className="rounded-lg bg-red-600 px-4 py-3 font-bold text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60">{cancelBusy?'Annulation...':'Oui, annuler'}</button></div></section></div>}
  </Shell>
}

function PatientAppointmentCalendar({appointments,upcoming,onSelect}:{appointments:PatientAppointment[];upcoming:PatientAppointment[];onSelect:(appointment:PatientAppointment)=>void}){
  const{t,i18n}=useTranslation()
  const calendarLocale=i18n.language.startsWith('ar')?arLocale:i18n.language.startsWith('en')?enGbLocale:frLocale
  const events=useMemo(()=>appointments.map(item=>({
    id:item.id,
    title:item.doctor_name??item.cabinet_name??'Rendez-vous médical',
    start:`${item.date}T${item.start_time}`,
    end:`${item.date}T${item.end_time}`,
    classNames:[`appointment-${item.status}`],
    extendedProps:{appointment:item},
  })),[appointments])
  return <section className="patient-calendar mt-5 overflow-hidden rounded-2xl border border-atlas-line bg-white shadow-sm">
    <div className="grid xl:grid-cols-[minmax(0,1fr)_300px]">
      <div className="calendar-shell min-w-0 p-3 sm:p-5">
        <FullCalendar
          plugins={[dayGridPlugin,timeGridPlugin]}
          locale={calendarLocale}
          initialView="dayGridMonth"
          headerToolbar={{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek'}}
          buttonText={{today:t('today',{defaultValue:"Aujourd’hui"}),month:t('month',{defaultValue:'Mois'}),week:t('week',{defaultValue:'Semaine'})}}
          events={events}
          eventClick={info=>onSelect(info.event.extendedProps.appointment as PatientAppointment)}
          eventContent={info=><div className="min-w-0 px-1 py-0.5"><b className="block truncate text-[11px]">{info.timeText&&`${info.timeText} · `}{info.event.title}</b><span className="block truncate text-[10px] opacity-75">{appointmentStatuses[(info.event.extendedProps.appointment as PatientAppointment).status]?.label??(info.event.extendedProps.appointment as PatientAppointment).status}</span></div>}
          height="auto"
          nowIndicator
          dayMaxEvents={3}
          slotMinTime="07:00:00"
          slotMaxTime="21:00:00"
          allDaySlot={false}
          firstDay={1}
        />
      </div>
      <aside className="border-t border-atlas-line bg-slate-50/70 p-5 xl:border-l xl:border-t-0">
        <div className="flex items-center justify-between gap-2"><div><p className="text-[11px] font-black uppercase tracking-wider text-atlas-teal">À venir</p><h3 className="mt-1 font-display text-lg font-bold">Mes prochains rendez-vous</h3></div><span className="grid h-8 min-w-8 place-items-center rounded-full bg-atlas-mist px-2 text-xs font-black text-atlas-teal">{upcoming.length}</span></div>
        <div className="mt-4 space-y-3">{upcoming.slice(0,4).map(item=>{const status=appointmentStatuses[item.status]??{label:item.status,style:'bg-slate-100 text-slate-700'};return <button type="button" key={item.id} onClick={()=>onSelect(item)} className="w-full rounded-xl border border-atlas-line bg-white p-3 text-left shadow-sm hover:border-atlas-teal"><div className="flex items-start gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-lg bg-atlas-mist text-center"><b className="text-sm leading-none text-atlas-teal">{new Date(`${item.date}T12:00:00`).toLocaleDateString(patientLocale(),{day:'2-digit'})}</b><span className="text-[9px] font-black uppercase text-atlas-petrol">{new Date(`${item.date}T12:00:00`).toLocaleDateString(patientLocale(),{month:'short'})}</span></div><div className="min-w-0"><b className="block truncate text-sm">{item.doctor_name??'Médecin du cabinet'}</b><p className="mt-1 text-xs text-slate-500">{item.start_time.slice(0,5)} – {item.end_time.slice(0,5)}</p><span className={`mt-2 inline-flex rounded-full px-2 py-0.5 text-[9px] font-bold ${status.style}`}>{status.label}</span></div></div></button>})}{!upcoming.length&&<div className="rounded-xl border border-dashed border-atlas-line bg-white p-6 text-center"><CalendarDays className="mx-auto text-slate-300" size={28}/><p className="mt-2 text-sm font-bold text-slate-600">Agenda libre</p><p className="mt-1 text-xs text-slate-400">Aucun rendez-vous à venir.</p></div>}</div>
        <div className="mt-5 border-t border-atlas-line pt-4"><p className="text-[10px] font-black uppercase tracking-wider text-slate-400">Statuts</p><div className="mt-3 flex flex-wrap gap-2">{['requested','planned','confirmed','completed','cancelled','absent'].map(status=><span key={status} className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${appointmentStatuses[status].style}`}>{appointmentStatuses[status].label}</span>)}</div></div>
      </aside>
    </div>
  </section>
}

function PatientBookingCalendar({availability,appointments,page,selectedDate,selectedTime,onPage,onSelect}:{availability:AvailabilityDay[];appointments:PatientAppointment[];page:number;selectedDate:string;selectedTime:string;onPage:(page:number)=>void;onSelect:(date:string,start:string,end:string)=>void}){
  const pages=Math.max(1,Math.ceil(availability.length/5))
  const days=availability.slice(page*5,page*5+5)
  const times=useMemo(()=>Array.from(new Set(days.flatMap(day=>day.slots.map(slot=>slot.start_time)))).sort(),[days])
  const dayByDate=useMemo(()=>new Map(days.map(day=>[day.date,day])),[days])
  const ownAppointment=useMemo(()=>new Map(appointments.map(item=>[`${item.date}-${item.start_time.slice(0,5)}`,item])),[appointments])
  if(!availability.length)return <div className="mt-5 rounded-xl bg-amber-50 p-8 text-center"><CalendarDays className="mx-auto text-amber-500" size={34}/><p className="mt-3 font-bold text-amber-900">Aucun créneau disponible actuellement</p><p className="mt-1 text-sm text-amber-700">Choisissez un autre médecin ou réessayez plus tard.</p></div>
  return <div className="mt-4 overflow-hidden rounded-xl border border-atlas-line bg-white">
    <div className="flex items-center justify-between border-b border-atlas-line bg-atlas-mist/60 px-3 py-2"><button type="button" disabled={page===0} onClick={()=>onPage(page-1)} className="rounded-md border border-atlas-line bg-white p-1.5 text-atlas-petrol disabled:opacity-30"><ChevronLeft size={16}/></button><div className="text-center"><b className="text-xs">Agenda des disponibilités</b><p className="text-[10px] text-slate-500">Semaine {page+1} sur {pages}</p></div><button type="button" disabled={page>=pages-1} onClick={()=>onPage(page+1)} className="rounded-md border border-atlas-line bg-white p-1.5 text-atlas-petrol disabled:opacity-30"><ChevronRight size={16}/></button></div>
    <div className="overflow-x-auto">
      <div className="min-w-[620px]" style={{display:'grid',gridTemplateColumns:`54px repeat(${days.length}, minmax(105px, 1fr))`}}>
        <div className="border-b border-r border-atlas-line bg-slate-50"/>
        {days.map(day=><div key={day.date} className="border-b border-r border-atlas-line bg-slate-50 px-1 py-2 text-center last:border-r-0"><span className="block text-[10px] font-black uppercase text-atlas-teal">{new Date(`${day.date}T12:00:00`).toLocaleDateString(patientLocale(),{weekday:'short'})}</span><b className="mt-0.5 block text-xs">{new Date(`${day.date}T12:00:00`).toLocaleDateString(patientLocale(),{day:'2-digit',month:'2-digit'})}</b></div>)}
        {times.flatMap(time=>[
          <div key={`time-${time}`} className="border-b border-r border-atlas-line bg-slate-50 px-1 py-3 text-center text-[10px] font-bold text-slate-500">{time}</div>,
          ...days.map(day=>{
            const slot=dayByDate.get(day.date)?.slots.find(item=>item.start_time===time)
            const appointment=ownAppointment.get(`${day.date}-${time}`)
            const selected=selectedDate===day.date&&selectedTime===time
            return <div key={`${day.date}-${time}`} className="min-h-[52px] border-b border-r border-atlas-line p-1 last:border-r-0">{appointment?<div className="h-full rounded-md border-l-3 border-atlas-petrol bg-slate-100 p-1.5 text-[10px]"><b>Votre rendez-vous</b><span className="mt-0.5 block text-slate-500">{appointment.status}</span></div>:slot?<button type="button" onClick={()=>onSelect(day.date,slot.start_time,slot.end_time)} className={`h-full w-full rounded-md border p-1.5 text-left text-[10px] font-bold transition ${selected?'border-atlas-teal bg-atlas-teal text-white shadow-md':'border-emerald-200 bg-emerald-50 text-emerald-800 hover:border-atlas-teal hover:bg-atlas-mist'}`}><span className="block">{slot.start_time}–{slot.end_time}</span><span className={`mt-0.5 block text-[9px] ${selected?'text-white/75':'text-emerald-600'}`}>{selected?'Sélectionné':'Disponible'}</span></button>:<div className="h-full rounded-md bg-slate-50/60"/>}</div>
          })
        ])}
      </div>
    </div>
    <div className="flex flex-wrap items-center gap-3 border-t border-atlas-line bg-slate-50 px-3 py-2 text-[10px] font-semibold text-slate-500"><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded bg-emerald-100 ring-1 ring-emerald-300"/>Disponible</span><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded bg-atlas-teal"/>Sélectionné</span><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded bg-slate-200"/>Votre rendez-vous</span></div>
  </div>
}

export function PatientReviewsPage({onNavigate}:{onNavigate:(p:string)=>void}){
  const{token,profile}=useProfile();const[rows,setRows]=useState<Array<{id:string;doctor_id:string;doctor_name:string;rating:number;comment:string;created_at:string}>>([]);const[editing,setEditing]=useState<string|null>(null);const[rating,setRating]=useState(5);const[comment,setComment]=useState('');const[message,setMessage]=useState('')
  const load=useCallback(()=>apiList<any>('/patient/reviews',token).then(setRows),[token]);useEffect(()=>{void load()},[load])
  function edit(item:typeof rows[number]){setEditing(item.id);setRating(item.rating);setComment(item.comment);setMessage('')}
  async function save(event:FormEvent){event.preventDefault();if(!editing)return;try{await apiUpdate(`/patient/reviews/${editing}`,token,{rating,comment});setEditing(null);setComment('');setRating(5);setMessage('Votre avis a été modifié avec succès.');await load()}catch(reason){setMessage(reason instanceof Error?reason.message:'Modification impossible.')}}
  return <Shell onNavigate={onNavigate} profile={profile}><div className="flex flex-wrap items-end justify-between gap-4"><Header title="Mes avis" subtitle="Retrouvez et modifiez les avis publiés après vos consultations."/><button onClick={()=>onNavigate('/patient/find-doctor')} className="rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white">Donner un nouvel avis</button></div>{message&&<p className="mt-5 rounded-lg bg-emerald-50 p-4 font-bold text-emerald-700">{message}</p>}<div className="mt-6 space-y-3">{rows.map(item=><article key={item.id} className="rounded-xl border border-atlas-line bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>{item.doctor_name}</b><p className="mt-1 text-xs text-slate-400">Publié le {new Date(item.created_at).toLocaleDateString(patientLocale(),{dateStyle:'long'})}</p></div><div className="flex gap-1">{[1,2,3,4,5].map(value=><Star key={value} size={17} className={value<=item.rating?'fill-amber-400 text-amber-400':'text-slate-200'}/>)}</div></div><p className="mt-4 text-sm leading-6 text-slate-600">{item.comment}</p><button onClick={()=>edit(item)} className="mt-4 rounded-lg bg-atlas-mist px-4 py-2 text-sm font-bold text-atlas-teal">Modifier mon avis</button></article>)}{!rows.length&&<div className="rounded-xl border border-atlas-line bg-white p-12 text-center"><Star className="mx-auto text-slate-300" size={40}/><p className="mt-3 font-bold">Vous n’avez encore publié aucun avis</p><p className="mt-1 text-sm text-slate-500">Choisissez « Donner un nouvel avis », puis ouvrez la fiche de votre médecin.</p></div>}</div>{editing&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/55 p-4"><form onSubmit={save} className="w-full max-w-xl rounded-2xl bg-white p-6 shadow-2xl"><h2 className="font-display text-2xl font-bold">Modifier mon avis</h2><div className="mt-5 flex gap-1">{[1,2,3,4,5].map(value=><button type="button" key={value} onClick={()=>setRating(value)}><Star size={25} className={value<=rating?'fill-amber-400 text-amber-400':'text-slate-200'}/></button>)}</div><textarea required minLength={5} value={comment} onChange={event=>setComment(event.target.value)} rows={6} className="mt-4 w-full rounded-lg border border-atlas-line p-3 outline-none focus:border-atlas-teal"/><div className="mt-4 flex justify-end gap-3"><button type="button" onClick={()=>setEditing(null)} className="rounded-lg border px-4 py-2.5 font-bold text-slate-600">Annuler</button><button className="rounded-lg bg-atlas-teal px-5 py-2.5 font-bold text-white">Enregistrer</button></div></form></div>}</Shell>
}

const endpoints:Record<string,{title:string;subtitle:string}>={visits:{title:'myVisits',subtitle:'visitsSubtitle'},documents:{title:'myDocuments',subtitle:'documentsSubtitle'},prescriptions:{title:'myPrescriptions',subtitle:'prescriptionsSubtitle'},cnss:{title:'myCnss',subtitle:'cnssSubtitle'},payments:{title:'myPayments',subtitle:'paymentsSubtitle'}}
const detailLabels:Record<string,string>={visit_date:'Date de visite',reason:'Motif',notes:'Compte rendu et observations',status:'Statut',attendance_status:'Présence',actual_start_time:'Début réel',actual_end_time:'Fin réelle',duration_seconds:'Durée',document_type:'Type de document',description:'Description',document_date:'Date du document',original_filename:'Fichier original',mime_type:'Format',file_size:'Taille',source:'Source',version:'Version',prescription_number:'Numéro d’ordonnance',consultation_date:'Date de consultation',location:'Lieu',content:'Prescription et remarques',amount:'Montant payé',method:'Mode de paiement',payment_type:'Type de règlement',paid_at:'Date de paiement',reference:'Référence',note:'Note',cheque_bank:'Banque',cheque_number:'Numéro du chèque',cheque_issue_date:'Date d’émission',cheque_cashing_date:'Encaissement prévu',cheque_status:'Statut du chèque'}
function detailValue(key:string,value:any){
  if(value===null||value===undefined||value==='')return null
  if(key==='amount')return patientMoney(value)
  if(key==='file_size')return `${Math.max(1,Math.round(Number(value)/1024))} Ko`
  if(key==='duration_seconds')return `${Math.round(Number(value)/60)} min`
  if(key.includes('date')||key.endsWith('_at')){const parsed=new Date(String(value).length===10?`${value}T12:00:00`:value);if(!Number.isNaN(parsed.getTime()))return parsed.toLocaleString(patientLocale(),String(value).length===10?{dateStyle:'long'}:{dateStyle:'long',timeStyle:'short'})}
  return String(value).replaceAll('_',' ')
}
function PatientDetailDialog({kind,item,onClose,onDownload,onPrescription,onReceipt}:{kind:string;item:any;onClose:()=>void;onDownload:(id:string)=>void;onPrescription:(id:string)=>void;onReceipt:(id:string)=>void}){
  const keys=kind==='visits'?['visit_date','reason','notes','attendance_status','status','actual_start_time','actual_end_time','duration_seconds']:kind==='documents'?['document_type','description','document_date','original_filename','mime_type','file_size','source','version']:kind==='prescriptions'?['prescription_number','consultation_date','location','content']:['amount','method','payment_type','paid_at','status','reference','note','cheque_bank','cheque_number','cheque_issue_date','cheque_cashing_date','cheque_status']
  return <div className="fixed inset-0 z-[80] grid place-items-center bg-slate-950/55 p-4" role="dialog" aria-modal="true"><section className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><header className="sticky top-0 flex items-start justify-between gap-4 border-b border-atlas-line bg-white p-5"><div><p className="text-xs font-black uppercase tracking-widest text-atlas-teal">Détail du module</p><h2 className="mt-1 font-display text-2xl font-bold">{item.title??item.reference??(kind==='prescriptions'?'Ordonnance':kind==='payments'?'Paiement':'Visite')}</h2></div><button onClick={onClose} className="rounded-full bg-slate-100 p-2 text-slate-600 hover:bg-slate-200" aria-label="Fermer"><X/></button></header><div className="grid gap-3 p-5 sm:grid-cols-2">{keys.map(key=>{const value=detailValue(key,item[key]);return value?<div key={key} className={`${key==='notes'||key==='description'||key==='content'||key==='note'?'sm:col-span-2':''} rounded-xl border border-atlas-line bg-slate-50 p-4`}><p className="text-[11px] font-black uppercase tracking-wide text-slate-400">{detailLabels[key]}</p><p className="mt-2 whitespace-pre-wrap text-sm font-semibold leading-6 text-slate-700">{value}</p></div>:null})}{kind==='prescriptions'&&Array.isArray(item.items)&&item.items.length>0&&<div className="sm:col-span-2"><h3 className="mb-3 font-bold">Médicaments prescrits</h3><div className="space-y-2">{item.items.map((drug:any,index:number)=><article key={index} className="rounded-xl border border-atlas-line p-4"><b>{drug.medication_name??drug.name??`Médicament ${index+1}`}</b><p className="mt-1 text-sm text-slate-600">{[drug.dosage,drug.form,drug.route,drug.frequency,drug.duration].filter(Boolean).join(' · ')}</p>{(drug.instructions||drug.notes)&&<p className="mt-2 text-sm text-slate-500">{drug.instructions??drug.notes}</p>}</article>)}</div></div>}</div><footer className="flex flex-wrap justify-end gap-3 border-t border-atlas-line p-5">{kind==='documents'&&<button onClick={()=>onDownload(item.id)} className="inline-flex items-center gap-2 rounded-lg bg-atlas-teal px-5 py-2.5 font-bold text-white"><Eye size={17}/>Ouvrir le document</button>}{kind==='prescriptions'&&<button onClick={()=>onPrescription(item.id)} className="inline-flex items-center gap-2 rounded-lg bg-atlas-teal px-5 py-2.5 font-bold text-white"><FileText size={17}/>Voir / imprimer</button>}{kind==='payments'&&<button onClick={()=>onReceipt(item.id)} className="inline-flex items-center gap-2 rounded-lg bg-atlas-teal px-5 py-2.5 font-bold text-white"><Download size={17}/>Télécharger le reçu</button>}</footer></section></div>
}
export function PatientListPage({kind,onNavigate}:{kind:keyof typeof endpoints;onNavigate:(p:string)=>void}){
  const{token,profile}=useProfile();const[rows,setRows]=useState<any[]>([]);const[fees,setFees]=useState<any[]>([]);const[finance,setFinance]=useState<any>(null);const[selected,setSelected]=useState<any>(null);const[error,setError]=useState('')
  useEffect(()=>{
    let active=true
    setError('');setSelected(null);setRows([]);setFees([]);setFinance(null)
    if(kind!=='payments'){
      apiList<any>(`/patient/${kind}`,token).then(data=>{if(active)setRows(data)}).catch(reason=>{if(active)setError(reason instanceof Error?reason.message:'Chargement impossible.')})
      return()=>{active=false}
    }
    Promise.allSettled([
      apiList<any>('/patient/payments',token),
      apiList<any>('/patient/honoraires',token),
      apiGet<any>('/patient/dashboard',token),
    ]).then(results=>{
      if(!active)return
      const [paymentsResult,feesResult,dashboardResult]=results
      if(paymentsResult.status==='fulfilled')setRows(paymentsResult.value)
      else setError(paymentsResult.reason instanceof Error&&paymentsResult.reason.message!=='Erreur inconnue'?paymentsResult.reason.message:'Impossible de charger l’historique des paiements.')
      if(feesResult.status==='fulfilled')setFees(feesResult.value)
      if(dashboardResult.status==='fulfilled')setFinance(dashboardResult.value)
    })
    return()=>{active=false}
  },[kind,token])
  async function download(id:string){const r=await apiPreview(`/patient/documents/${id}/download`,token);window.open(r.url,'_blank')}
  async function prescriptionPdf(id:string){const r=await apiPreview(`/patient/prescriptions/${id}/pdf`,token);window.open(r.url??`/api/patient/prescriptions/${id}/pdf`,'_blank')}
  async function receipt(id:string){try{await apiDownload(`/patient/receipts/${id}/download`,token,`recu-${id}.pdf`)}catch(reason){setError(reason instanceof Error?reason.message:'Téléchargement du reçu impossible.')}}
  return <Shell onNavigate={onNavigate} profile={profile}><Header title={endpoints[kind].title} subtitle={endpoints[kind].subtitle}/>{error&&<p className="mt-5 rounded-lg bg-red-50 p-4 font-bold text-red-700">{error}</p>}{kind==='payments'&&finance?.financial_summary&&<PatientFinancialSummary summary={finance.financial_summary} dues={finance.upcoming_due_dates??[]} items={finance.financial_items??[]} fallbackFees={fees} fallbackPayments={rows} onNavigate={onNavigate}/>} {kind==='payments'&&fees.length>0&&<section className="mt-6"><h2 className="font-display text-xl font-bold">Honoraires et reste à payer</h2><div className="mt-3 grid gap-3 md:grid-cols-2">{fees.map(fee=><article key={fee.id} className="rounded-xl border border-atlas-line bg-white p-4"><div className="flex justify-between gap-3"><div><b>{fee.title??'Honoraire'}</b><p className="mt-1 text-xs font-semibold uppercase text-slate-400">{fee.fee_type??'Consultation'} · {String(fee.status).replaceAll('_',' ')}</p></div><strong className="text-atlas-teal">{patientMoney(fee.amount)}</strong></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><div className="rounded-lg bg-emerald-50 p-3"><span className="block text-xs text-emerald-700">Payé</span><b>{patientMoney(fee.paid_amount)}</b></div><div className="rounded-lg bg-amber-50 p-3"><span className="block text-xs text-amber-700">RAP</span><b>{patientMoney(fee.remaining_amount)}</b></div></div></article>)}</div></section>}<section className="mt-6"><h2 className="font-display text-xl font-bold">{kind==='payments'?'Historique des paiements':'Éléments disponibles'}</h2><div className="mt-4 grid gap-4 md:grid-cols-2">{rows.map(x=>{const attendance=x.attendance_status??x.status;const paymentDate=kind==='payments'&&x.paid_at?new Date(x.paid_at).toLocaleString(patientLocale(),{dateStyle:'long',timeStyle:'short'}):null;const paymentMethod:Record<string,string>={cash:'Espèces',card:'Carte bancaire',transfer:'Virement',cheque:'Chèque'};return <article key={x.id} className="rounded-xl border bg-white p-5 shadow-sm"><div className="flex flex-wrap justify-between gap-3"><div><b>{paymentDate??x.title??x.reference??x.visit_date??`Ordonnance du ${new Date(x.created_at).toLocaleDateString(patientLocale())}`}</b><p className="mt-1 line-clamp-3 text-sm text-slate-500">{kind==='payments'?(paymentMethod[x.method]??x.method):x.document_type??x.reason??x.content??''}</p></div>{kind==='visits'?<span className={`h-fit rounded-full px-3 py-1 text-xs font-bold ${attendance==='absent'?'bg-red-50 text-red-700':'bg-emerald-50 text-emerald-700'}`}>{attendance==='absent'?'Absent':'Présent'}</span>:<span className="font-bold text-atlas-teal">{x.status??(x.amount?patientMoney(x.amount):'')}</span>}</div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={()=>setSelected(x)} className="inline-flex items-center gap-2 rounded-lg border border-atlas-line px-4 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50"><Eye size={16}/>Voir les détails</button>{kind==='documents'&&profile?.settings.patient_can_download_documents&&<button onClick={()=>download(x.id)} className="rounded-lg bg-atlas-mist px-4 py-2 text-sm font-bold text-atlas-teal">Ouvrir</button>}{kind==='prescriptions'&&<button onClick={()=>prescriptionPdf(x.id)} className="rounded-lg bg-atlas-mist px-4 py-2 text-sm font-bold text-atlas-teal">Imprimer</button>}{kind==='payments'&&<button type="button" onClick={()=>void receipt(x.id)} className="inline-flex items-center gap-2 rounded-lg bg-atlas-mist px-4 py-2 text-sm font-bold text-atlas-teal"><Download size={16}/>Reçu</button>}</div></article>})}{!rows.length&&!error&&<p className="rounded-xl border bg-white p-8 text-center text-slate-500 md:col-span-2">Aucun élément disponible.</p>}</div></section>{selected&&<PatientDetailDialog kind={kind} item={selected} onClose={()=>setSelected(null)} onDownload={download} onPrescription={prescriptionPdf} onReceipt={receipt}/>}</Shell>
}

export function PatientProfile({onNavigate}:{onNavigate:(p:string)=>void}){
  const{t,i18n}=useTranslation()
  const{token,profile,setProfile}=useProfile()
  const[form,setForm]=useState({email:'',phone:'',address:'',cnss_deposit_reminder_days:3})
  const[passwords,setPasswords]=useState({current_password:'',new_password:'',confirmation:''})
  const[passwordMsg,setPasswordMsg]=useState<{kind:'success'|'error';text:string}|null>(null)
  const[passwordBusy,setPasswordBusy]=useState(false)
  const[showPasswords,setShowPasswords]=useState(false)
  const[reviews,setReviews]=useState<Array<{id:string;doctor_name:string;rating:number;comment:string;created_at:string}>>([])
  const[msg,setMsg]=useState('')
  useEffect(()=>{if(profile)setForm({email:profile.email,phone:profile.phone??'',address:profile.address??'',cnss_deposit_reminder_days:profile.cnss_deposit_reminder_days??3})},[profile])
  useEffect(()=>{if(token)apiList<any>('/patient/reviews',token).then(setReviews).catch(()=>setReviews([]))},[token])
  async function submit(e:FormEvent){e.preventDefault();try{const p=await apiUpdate<Profile>('/patient/profile',token,form);setProfile(p);setMsg(t('profileUpdated'))}catch(e){setMsg(e instanceof Error?e.message:t('profileUpdateFailed'))}}
  async function changePassword(e:FormEvent){
    e.preventDefault()
    setPasswordMsg(null)
    if(passwords.new_password!==passwords.confirmation){setPasswordMsg({kind:'error',text:t('passwordConfirmationMismatch')});return}
    if(passwords.new_password.length<10){setPasswordMsg({kind:'error',text:t('passwordTooShort')});return}
    if(passwords.current_password===passwords.new_password){setPasswordMsg({kind:'error',text:t('passwordMustDiffer')});return}
    setPasswordBusy(true)
    try{
      await apiUpdate('/patient/change-password',token,{current_password:passwords.current_password,new_password:passwords.new_password})
      setPasswords({current_password:'',new_password:'',confirmation:''})
      setPasswordMsg({kind:'success',text:t('passwordChanged')})
    }catch(error){setPasswordMsg({kind:'error',text:error instanceof Error?error.message:t('passwordChangeFailed')})}
    finally{setPasswordBusy(false)}
  }
  return <Shell onNavigate={onNavigate} profile={profile}>
    <Header title="patientSettings" subtitle="patientSettingsSubtitle"/>
    <div className="mt-6"><InterfaceLanguageSettings/></div>
    {profile&&<form onSubmit={submit} className="mt-6 grid gap-4 rounded-xl border bg-white p-6 md:grid-cols-2">
      <div className="md:col-span-2"><h2 className="font-display text-xl font-bold">{t('personalDetails')}</h2><p className="mt-1 text-sm text-slate-500">{t('personalDetailsSubtitle')}</p></div>
      <Card label={t('lastName')} value={`${profile.first_name} ${profile.last_name}`}/>
      <Card label={t('birthDate')} value={new Date(`${profile.birth_date}T12:00:00`).toLocaleDateString(i18n.resolvedLanguage??i18n.language,{dateStyle:'long'})}/>
      <label><span className="font-bold">{t('email')}</span><input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="mt-2 w-full rounded-lg border p-3"/></label>
      <label><span className="font-bold">{t('phone')}</span><input type="tel" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} className="mt-2 w-full rounded-lg border p-3"/></label>
      <label className="md:col-span-2"><span className="font-bold">{t('address')}</span><input value={form.address} onChange={e=>setForm({...form,address:e.target.value})} className="mt-2 w-full rounded-lg border p-3"/></label>
      <label className="md:col-span-2"><span className="font-bold">{t('cnssDepositReminder')}</span><select value={form.cnss_deposit_reminder_days} onChange={e=>setForm({...form,cnss_deposit_reminder_days:Number(e.target.value)})} className="mt-2 w-full rounded-lg border bg-white p-3"><option value={0}>{t('sameDay')}</option><option value={1}>{t('oneDayBefore')}</option><option value={2}>{t('daysBefore',{count:2})}</option><option value={3}>{t('daysBefore',{count:3})}</option><option value={5}>{t('daysBefore',{count:5})}</option><option value={7}>{t('daysBefore',{count:7})}</option><option value={14}>{t('daysBefore',{count:14})}</option></select><small className="mt-2 block text-slate-500">{t('cnssDepositReminderHint')}</small></label>
      <button className="rounded-lg bg-atlas-teal p-3 font-bold text-white md:col-span-2">{t('save')}</button>
      {msg&&<p className="font-bold text-atlas-teal md:col-span-2">{msg}</p>}
    </form>}
    <section className="mt-6 rounded-xl border border-atlas-line bg-white p-6 shadow-sm">
      <div className="flex items-start gap-3"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-atlas-mist text-atlas-teal"><LockKeyhole size={21}/></span><div><p className="text-xs font-bold uppercase tracking-widest text-atlas-teal">{t('security')}</p><h2 className="mt-1 font-display text-2xl font-bold">{t('changeMyPassword')}</h2><p className="mt-1 text-sm text-slate-500">{t('passwordSecurityHint')}</p></div></div>
      <form onSubmit={changePassword} className="mt-5 grid gap-4 md:grid-cols-2">
        <label className="md:col-span-2"><span className="font-bold">{t('currentPassword')}</span><input required autoComplete="current-password" type={showPasswords?'text':'password'} value={passwords.current_password} onChange={e=>setPasswords({...passwords,current_password:e.target.value})} className="mt-2 w-full rounded-lg border border-atlas-line p-3 outline-none focus:border-atlas-teal"/></label>
        <label><span className="font-bold">{t('newPassword')}</span><input required minLength={10} maxLength={128} autoComplete="new-password" type={showPasswords?'text':'password'} value={passwords.new_password} onChange={e=>setPasswords({...passwords,new_password:e.target.value})} className="mt-2 w-full rounded-lg border border-atlas-line p-3 outline-none focus:border-atlas-teal"/></label>
        <label><span className="font-bold">{t('confirmNewPassword')}</span><input required minLength={10} maxLength={128} autoComplete="new-password" type={showPasswords?'text':'password'} value={passwords.confirmation} onChange={e=>setPasswords({...passwords,confirmation:e.target.value})} className="mt-2 w-full rounded-lg border border-atlas-line p-3 outline-none focus:border-atlas-teal"/></label>
        <div className="flex flex-wrap items-center justify-between gap-3 md:col-span-2"><button type="button" onClick={()=>setShowPasswords(value=>!value)} className="inline-flex items-center gap-2 text-sm font-bold text-slate-600">{showPasswords?<EyeOff size={17}/>:<Eye size={17}/>} {t(showPasswords?'hidePasswords':'showPasswords')}</button><button disabled={passwordBusy} className="rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white disabled:cursor-not-allowed disabled:opacity-60">{t(passwordBusy?'changingPassword':'changePassword')}</button></div>
        {passwordMsg&&<p role="status" className={`rounded-lg p-4 text-sm font-bold md:col-span-2 ${passwordMsg.kind==='success'?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'}`}>{passwordMsg.text}</p>}
      </form>
    </section>
    <section className="mt-6 rounded-xl border border-atlas-line bg-white p-6 shadow-sm">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div><p className="text-xs font-bold uppercase tracking-widest text-atlas-teal">{t('myExperience')}</p><h2 className="mt-1 font-display text-2xl font-bold">{t('myReviews')}</h2><p className="mt-1 text-sm text-slate-500">{t('myReviewsCount',{count:reviews.length})}</p></div>
        <button type="button" onClick={()=>onNavigate('/patient/reviews')} className="rounded-lg bg-atlas-teal px-5 py-3 font-bold text-white">{t('viewAllMyReviews')}</button>
      </div>
      <div className="mt-5 grid gap-3 md:grid-cols-2">
        {reviews.slice(0,4).map(review=><article key={review.id} className="rounded-lg border border-atlas-line bg-atlas-cloud p-4"><div className="flex flex-wrap items-center justify-between gap-2"><b>{review.doctor_name}</b><span className="flex">{[1,2,3,4,5].map(value=><Star key={value} size={15} className={value<=review.rating?'fill-amber-400 text-amber-400':'text-slate-200'}/>)}</span></div><p className="mt-2 line-clamp-2 text-sm leading-6 text-slate-600">{review.comment}</p><p className="mt-2 text-xs text-slate-400">{new Date(review.created_at).toLocaleDateString(i18n.resolvedLanguage??i18n.language,{dateStyle:'long'})}</p></article>)}
        {!reviews.length&&<div className="rounded-lg bg-atlas-cloud p-6 text-center md:col-span-2"><Star className="mx-auto text-slate-300" size={34}/><p className="mt-3 font-bold">{t('noPublishedReview')}</p><button type="button" onClick={()=>onNavigate('/patient/find-doctor')} className="mt-3 font-bold text-atlas-teal">{t('giveFirstReview')}</button></div>}
      </div>
    </section>
  </Shell>
}
